"""The tp4/octo-3 window pack (scripts/ci/references/fusion-jobs/O3), generated (stdlib only).

    python3 scripts/ci/make_octo3_jobs.py --write   regenerate the pack
    python3 scripts/ci/make_octo3_jobs.py --check   exit 1 if the checked-in pack is not what this generates

ONE image (tp4-octo3-1, built by B0 from the pushed branch head WITH the K64j-OQ graft so that the oneq arm can run on it), ONE window: octo-T8 and its three levers on the fused stack. The
question the pack answers is the shipping one: octo-everywhere (every eligible 8-live round on the octo block, QWEN_FAST_OCTO=live) against today (the fused stack's own two-M3-block rounds),
at 4k, at 32k and at 120k, on the same image. The arms are the gate-only twins generated by make_octo3_profiles.py; the SHIP CANDIDATES (traffic profiles under an owner waiver) and their gate
pack are make_fusion_profiles.py's (references/fusion-jobs/ship-traffic-o3*) and are not touched by anything here.
"""

import argparse
from pathlib import Path
import sys

import make_fusion_jobs as jobs
import make_fusion_profiles as fusion
import make_octo3_profiles as octo3

HERE = Path(__file__).resolve().parent
FOLDER = HERE / 'references' / 'fusion-jobs' / 'O3'
RB_FOLDER = HERE / 'references' / 'fusion-jobs' / 'RB'
IMAGE = 'tp4-octo3-1'
RB_IMAGE = 'tp4-fusion-1'

CONTROL = octo3.FX_ALL
OCTO = octo3.FX_ALL + '-octo3'
QUAD = octo3.FX_ALL + '-octo3-quaddraft'
AUDIT = octo3.FX_ALL + '-octo3-audit'
PREFILL_AUDIT = octo3.FX_ALL_PREFILL + '-octo3-audit'
PRODUCTION = fusion.PARENT

DEEP = 'concurrent8_code_32k_long,concurrent8_code_128k_long'
TIMED_TESTS = 'warmup,concurrent8_steady,concurrent8_code_32k,concurrent8_code_128k,' + DEEP
QUAD_TESTS = 'warmup,concurrent8_steady,concurrent8_code_32k_long'
AUDIT_TESTS = 'warmup,coding,parked_turns,concurrent8_steady'
PREFILL_AUDIT_TESTS = 'warmup,prefill_ladder_solo,concurrent8_steady'

HEADER = """# A committed TEMPLATE of .github/c2-serving-job.env for the tp4/octo-3 window (octo-T8 and its three levers on the fused stack; scripts/ci/c2_serving_job.py parses it): copy it over
# .github/c2-serving-job.env on a throwaway commit of tp4/octo-3 and push a tag experiment/c2-serving-vN, ONE TAG AT A TIME (wait for the run to finish; never cancel a running card job).
# Nothing here names a rig, a card, a host or a registry: the cards are resolved at run time. The jobs are templates only: no tag is pushed from the branch by its author. ORDER.txt has the
# order, the stop rules, the minutes and the read rules.
# ONE IMAGE FOR THE WHOLE WINDOW: C2_IMAGE_TAG=%(image)s is the tag B0 builds from the pushed branch head WITH the K64j-OQ graft (the oneq arm needs its binary; every other arm runs that
# binary with the lever off). A commit of a file the image carries needs a new B0 build and a new tag in every template. This window never stops, starts or hands back the node agent."""

ARC = ('TIMED: the ARC runner sets are at ZERO for this job (ORDER.txt, ARC-ZERO); no build, no CI push, no other job beside it.')
TELEMETRY = ('TELEMETRY (C2_TELEMETRY=1, scripts/ci/card_telemetry.py): the read-only ARC sidecar samples every chip once a second through the smoke step; read telemetry-smoke/telemetry-summary.txt beside '
             'the result, and the first [TELEMETRY] line must say decode check ok. A gain that comes with a different loaded AICLK between the arms is the clocks, not the lever.')
OCTO_READ = ('python3 scripts/ci/octo_judge.py --container-log <container log> --profile %s clean: one "[OCTO] admitted mode=live" line, the UNQUALIFIED lines, at least 16 rounds with shape=octo '
             'at 8 live and rows=8 (the positive control: written after the octo block\'s own verify counter moved), no counted m3 round under live, no program compiled on the first octo round, '
             'the K64j geometry line (extent replay engaged segments=8 flags=0x21 ... G8B1) and the factory line for the bundle\'s launch size (entries=4 kv_share=false), and the lever rules: the octo draft '
             'engaged once and serving at least half of the 8-live octo rounds, the bundle engaged ONCE (the latch: the warm and the captured fixture build one bundle) with its call line, the glue8 engaged '
             'line for every site at users=8 rows=8 and 48 layers, no fallback, disabled or fell-back line anywhere.')

# (name, mode, minutes, actions, profile, tests, telemetry, box, needs, why, extras)


